using Microsoft.Dynamics365.LocalizationFramework;
/// <summary>
/// designed from AVA
/// </summary>
[ExtensionOf(classStr(ERPrintMgmtDataProviderReport))]
internal final class AVAERPrintMgmtDataProviderReport_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_mappingRun">_mappingRun</param>
protected void preRunAction(ERIFormatMappingRun _mappingRun)
{
    AVAERReportToMemory     reportToMemory;
    next preRunAction(_mappingRun);
    //AVASalesQuotationController_PrintInMemory       salesQuotationController_PrintInMemory = reportRunController as AVASalesQuotationController_PrintInMemory;
    SRSPrintDestinationSettings   curPrintSettings;


    if(reportDataContract.parmDoNotSaveFileIM())
    {
        Common printInMemoryRecord = reportDataContract.parmReportRecordIM();
        select firstonly reportToMemory
        where reportToMemory.refRecId == printInMemoryRecord.RecId
            && reportToMemory.RefTableId == printInMemoryRecord.TableId
            && reportToMemory.ReportName == printMgmtPrintSettingDetail.parmReportFormatName();

        if (!reportToMemory)
        {
            reportToMemory.RefRecId   = printInMemoryRecord.RecId;
            reportToMemory.RefTableId = printInMemoryRecord.TableId;
            reportToMemory.ReportName = printMgmtPrintSettingDetail.parmReportFormatName();
            reportToMemory.insert();
        }

        ERIFileDestinationFactoryHost factoryHost = ERCast::asObject(_mappingRun) as ERIFileDestinationFactoryHost;
        if (factoryHost)
        {
            ERIFileDestinationFactory fileDestinationFactory = factoryHost.getFileDestinationFactory();
            factoryHost.setFileDestinationFactory(AVAERMemoryDestinationFactory::construct(fileDestinationFactory,reportToMemory ));
        }

    }
}
